<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['grade_id'];$action=$_POST['action']??'';$uid=(int)$_SESSION['user_id'];if($action==='approve'){$q=$conn->prepare('UPDATE grades SET grade_status="approved" WHERE grade_id=? AND grade_status="submitted"');$q->bind_param('i',$id);$q->execute();audit($conn,$uid,'grade_approved','grade',$id);}elseif($action==='finalize'){$q=$conn->prepare('UPDATE grades SET grade_status="finalized",finalized_at=NOW() WHERE grade_id=? AND grade_status IN("submitted","approved")');$q->bind_param('i',$id);$q->execute();audit($conn,$uid,'grade_finalized','grade',$id);}elseif($action==='release'){$q=$conn->prepare('UPDATE grades SET grade_status="released",released_at=NOW() WHERE grade_id=? AND grade_status="finalized"');$q->bind_param('i',$id);$q->execute();audit($conn,$uid,'grade_released','grade',$id);}flash('Grade status updated.');go('/spi/admin/grades.php');}
$rows=$conn->query('SELECT g.grade_id,g.grade_value,g.grade_status,g.submitted_at,st.lrn,st.firstname,st.middle_name,st.lastname,sub.subject_code,sub.subject_name,gp.period_name,y.school_year_name,p.full_name FROM grades g JOIN students st ON st.student_id=g.student_id JOIN teacher_assignments a ON a.teacher_assignment_id=g.teacher_assignment_id JOIN teacher_profiles p ON p.user_id=a.teacher_id JOIN subjects sub ON sub.subject_id=a.subject_id JOIN grading_periods gp ON gp.grading_period_id=g.grading_period_id JOIN school_years y ON y.school_year_id=gp.school_year_id WHERE g.grade_status IN("submitted","approved","finalized") ORDER BY g.submitted_at DESC');page_start('Grade review');echo '<h1>Grade review and release</h1><p>Review submitted values against school policy before finalizing and releasing them. This page does not compute or validate a school grading formula.</p><div class="tablewrap"><table><tr><th>Student</th><th>Subject / period</th><th>Value</th><th>Teacher</th><th>Status</th><th>Action</th></tr>';while($g=$rows->fetch_assoc()){$next=['submitted'=>'approve','approved'=>'finalize','finalized'=>'release'][$g['grade_status']]??null;echo '<tr><td>'.e($g['lrn'].' · '.$g['lastname'].', '.$g['firstname'].' '.$g['middle_name']).'</td><td>'.e($g['school_year_name'].' · '.$g['subject_code'].' '.$g['subject_name'].' · '.$g['period_name']).'</td><td>'.e($g['grade_value']).'</td><td>'.e($g['full_name']).'</td><td>'.e($g['grade_status']).'</td><td>';if($next)echo '<form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="grade_id" value="'.(int)$g['grade_id'].'"><button name="action" value="'.$next.'">'.ucfirst($next).'</button></form>';echo '</td></tr>';}echo '</table></div>';page_end();
